import{_ as e,o as d,c as r,a2 as a}from"./chunks/framework.CGSzHL4z.js";const k=JSON.parse('{"title":"Mouse gestures","description":"","frontmatter":{},"headers":[],"relativePath":"reference/gestures.md","filePath":"reference/gestures.md","lastUpdated":1791952279000}'),o={name:"reference/gestures.md"};function s(i,t,l,n,h,c){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="mouse-gestures" tabindex="-1">Mouse gestures <a class="header-anchor" href="#mouse-gestures" aria-label="Permalink to &quot;Mouse gestures&quot;">​</a></h1><p>Clicks, drags and modifiers in each window.</p><h3 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h3><h4 id="ruler-and-regions" tabindex="-1">Ruler and regions <a class="header-anchor" href="#ruler-and-regions" aria-label="Permalink to &quot;Ruler and regions&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Gesture</th><th>What it does</th></tr></thead><tbody><tr><td>Drag the ruler</td><td>Scrubs. Snaps to markers, keys, regions, peaks, else whole frames; <kbd>Alt</kbd> flips snapping. Plays audio snippets over sounds.</td></tr><tr><td>Right click the ruler</td><td>Ruler menu (marker, loop, export region, insert/remove time).</td></tr><tr><td>Click a teammate&#39;s flag</td><td>Moves your playhead to theirs.</td></tr><tr><td>Right click a teammate&#39;s flag</td><td>The teammate menu (Follow, Jump, Ping).</td></tr><tr><td>Middle drag or <kbd>Space</kbd>+drag the ruler</td><td>Pans time.</td></tr><tr><td>Drag a marker flag or stem</td><td>Moves it (snaps).</td></tr><tr><td>Double click a marker flag or stem</td><td>Renames it.</td></tr><tr><td>Right click a marker flag or stem</td><td>Marker menu.</td></tr><tr><td>Drag the body of the loop bar or export bracket</td><td>Moves the region.</td></tr><tr><td>Drag an end of the loop bar or export bracket</td><td>Resizes the region.</td></tr><tr><td>Drag the scene end handle</td><td>Changes the scene length (snaps; <kbd>Alt</kbd> flips Snap).</td></tr></tbody></table><h4 id="keys-in-the-lanes" tabindex="-1">Keys in the lanes <a class="header-anchor" href="#keys-in-the-lanes" aria-label="Permalink to &quot;Keys in the lanes&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Gesture</th><th>What it does</th></tr></thead><tbody><tr><td>Click a key</td><td>Selects it.</td></tr><tr><td><kbd>Shift</kbd>+click / <kbd>Ctrl</kbd>+click a key</td><td>Adds to / toggles in the selection.</td></tr><tr><td>Double click a main key</td><td>Selects everything under it.</td></tr><tr><td>Drag a key</td><td>Moves the selected keys, with a chip and ghosts. Snaps; <kbd>Alt</kbd> flips Snap.</td></tr><tr><td><kbd>Ctrl</kbd>+drag a key</td><td>Moves a copy.</td></tr><tr><td>Drag on an empty lane</td><td>Box select; <kbd>Shift</kbd> / <kbd>Ctrl</kbd> adds.</td></tr><tr><td>Double click empty lane space on a row</td><td>Selects every key of that row (<kbd>Shift</kbd> / <kbd>Ctrl</kbd> adds).</td></tr><tr><td>Drag a scale handle</td><td>Retimes the selection about the other end; <kbd>Shift</kbd> about the playhead.</td></tr><tr><td>Drag the spread handle</td><td>Offsets joints&#39; keys in time (Random / Alternate / Staircase). Drag left for earlier; <kbd>Alt</kbd> for exact ticks.</td></tr><tr><td>Click the spread chip</td><td>Spread menu (mode, Reroll random).</td></tr><tr><td>Right click a key</td><td>Key menu.</td></tr></tbody></table><h4 id="action-lane" tabindex="-1">Action lane <a class="header-anchor" href="#action-lane" aria-label="Permalink to &quot;Action lane&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Gesture</th><th>What it does</th></tr></thead><tbody><tr><td>Click / <kbd>Shift</kbd>+click / <kbd>Ctrl</kbd>+click a block</td><td>Selects it / adds it / toggles it (keys let go).</td></tr><tr><td>Drag a block</td><td>Moves the selected blocks in time (their own tracks), with ghosts and a dotted trail. Snaps; <kbd>Alt</kbd> flips Snap.</td></tr><tr><td><kbd>Ctrl</kbd>+drag a block</td><td>Moves a copy.</td></tr><tr><td>Drag a sound bar, burst bar or block up or down</td><td>Moves that bar to the lane under the pointer (with any time move, one undo step). Works in the lanes and the action lane.</td></tr><tr><td>Drag a bar&#39;s end grip</td><td>Trims that end; the other stays (at least one frame). Shows a &quot;Length 60 f&quot; read-out.</td></tr><tr><td>Drag on an empty spot</td><td>Box-selects blocks (into other rows: their keys and blocks).</td></tr><tr><td>Double click an empty spot</td><td>Selects every block of the track.</td></tr><tr><td>Right click a block</td><td>Block menu.</td></tr><tr><td>Right click an empty spot</td><td>Track menu (Add block at that frame).</td></tr></tbody></table><h4 id="camera-row" tabindex="-1">Camera row <a class="header-anchor" href="#camera-row" aria-label="Permalink to &quot;Camera row&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Gesture</th><th>What it does</th></tr></thead><tbody><tr><td>Click / <kbd>Shift</kbd>+click / <kbd>Ctrl</kbd>+click a shot</td><td>Selects its switch key / adds it / toggles it (keys and blocks let go).</td></tr><tr><td>Drag a shot</td><td>Moves the selected switch keys in time. Taken frames are skipped; snaps, <kbd>Alt</kbd> flips Snap.</td></tr><tr><td><kbd>Ctrl</kbd>+drag a shot</td><td>Moves a copy.</td></tr><tr><td>Drag on an empty spot</td><td>Box-selects switch keys (down into the rows: their keys and blocks instead).</td></tr><tr><td>Double click an empty spot</td><td>Selects all switch keys.</td></tr><tr><td>Drag a shot&#39;s right end</td><td>Cuts the shot short (its Until; no camera live to the next key). Onto the next key, it runs to it again.</td></tr><tr><td>Right click a shot</td><td>Key menu: Switch to, Start at, End at, Extend to the next switch or scene end, Duplicate, Delete, Show in Inspector.</td></tr><tr><td>Right click an empty spot</td><td>Lane menu: Switch to at that frame, Add camera at view.</td></tr><tr><td>Right click the header</td><td>Header menu: Select all switch keys, Mute, Lock.</td></tr></tbody></table><h4 id="sound-and-effect-bars" tabindex="-1">Sound and effect bars <a class="header-anchor" href="#sound-and-effect-bars" aria-label="Permalink to &quot;Sound and effect bars&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Gesture</th><th>What it does</th></tr></thead><tbody><tr><td>Drag a sound bar&#39;s left edge</td><td>Trims the start (the audio stays put).</td></tr><tr><td>Drag a sound bar&#39;s right edge</td><td>Trims the end.</td></tr><tr><td>Double click a sound bar&#39;s right edge</td><td>Clears the end trim.</td></tr><tr><td><kbd>Ctrl</kbd>+drag a sound bar&#39;s right edge</td><td>Stretches the speed (0.25x to 4x).</td></tr><tr><td>Drag a sound bar&#39;s fade grip</td><td>Fades.</td></tr><tr><td>Drag a sound bar&#39;s loop handle</td><td>Moves the loop.</td></tr><tr><td>Right click a sound fade grip</td><td>Fade menu (shape, remove).</td></tr><tr><td>Drag an effect bar&#39;s end grip</td><td>Max life.</td></tr><tr><td>Drag an effect bar&#39;s min knob</td><td>Min life.</td></tr><tr><td>Double click an effect bar&#39;s grip</td><td>Resets it to the emitter&#39;s own.</td></tr></tbody></table><h4 id="rows" tabindex="-1">Rows <a class="header-anchor" href="#rows" aria-label="Permalink to &quot;Rows&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Gesture</th><th>What it does</th></tr></thead><tbody><tr><td>Click / <kbd>Ctrl</kbd>+click / <kbd>Shift</kbd>+click / <kbd>Ctrl+Shift</kbd>+click a row header</td><td>Select / toggle / range / add range.</td></tr><tr><td>Double click a row header</td><td>Keys the row at the playhead (like <kbd>K</kbd>).</td></tr><tr><td>Right click a row header</td><td>Row menu.</td></tr><tr><td>Drag the top or bottom edge of a sound or effect row header</td><td>Taller or shorter row. Double click resets.</td></tr><tr><td>Hover a row header</td><td>Shows the mute (eye) and lock buttons.</td></tr><tr><td>Drag the splitter (Split)</td><td>Shares the room between dope rows and curves.</td></tr></tbody></table><h4 id="scrolling-zoom-and-pan" tabindex="-1">Scrolling, zoom and pan <a class="header-anchor" href="#scrolling-zoom-and-pan" aria-label="Permalink to &quot;Scrolling, zoom and pan&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Gesture</th><th>What it does</th></tr></thead><tbody><tr><td>Mouse wheel over the lanes</td><td>Scrolls rows.</td></tr><tr><td><kbd>Ctrl</kbd>+wheel over the lanes, ruler or graph</td><td>Zooms time at the cursor.</td></tr><tr><td><kbd>Shift</kbd>+wheel over the lanes, ruler or graph</td><td>Pans time.</td></tr><tr><td><kbd>Ctrl+Shift</kbd>+wheel over the lanes</td><td>Compact or normal rows.</td></tr><tr><td>Middle drag or <kbd>Space</kbd>+drag over the lanes, ruler or graph</td><td>Pans.</td></tr></tbody></table><h4 id="curve-graph-and-ease" tabindex="-1">Curve graph and ease <a class="header-anchor" href="#curve-graph-and-ease" aria-label="Permalink to &quot;Curve graph and ease&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Gesture</th><th>What it does</th></tr></thead><tbody><tr><td>Click / <kbd>Shift</kbd> / <kbd>Ctrl</kbd> a key</td><td>Selects / adds / toggles.</td></tr><tr><td>Drag selected keys</td><td>Moves in time and value. <kbd>Shift</kbd> keeps one direction; <kbd>Alt</kbd> flips snapping.</td></tr><tr><td>Drag a tangent handle</td><td>Shapes both sides; <kbd>Alt</kbd> shapes one side.</td></tr><tr><td>Wheel / <kbd>Ctrl</kbd>+wheel / <kbd>Shift</kbd>+wheel / <kbd>Ctrl+Shift</kbd>+wheel</td><td>Pans values / zooms time / pans time / zooms values.</td></tr><tr><td>Wheel over the value axis</td><td>Zooms values at the pointer.</td></tr><tr><td>Drag a handle in the Ease canvas</td><td>Shapes the ease live. <kbd>Shift</kbd> snaps 0.05; <kbd>Alt</kbd> ignores snapping.</td></tr><tr><td>Click an Ease preset card</td><td>Applies it.</td></tr><tr><td>Right click a saved Ease preset card</td><td>Deletes it (after a confirm).</td></tr></tbody></table><h4 id="status-bar-toolbar-and-tooltips" tabindex="-1">Status bar, toolbar and tooltips <a class="header-anchor" href="#status-bar-toolbar-and-tooltips" aria-label="Permalink to &quot;Status bar, toolbar and tooltips&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Gesture</th><th>What it does</th></tr></thead><tbody><tr><td>Click snap, auto-key, fps or length in the status bar</td><td>Opens the menu or toggles.</td></tr><tr><td>Click a tool&#39;s chevron in the toolbar</td><td>The tool&#39;s options menu.</td></tr><tr><td>Hover any control</td><td>Tooltip (0.5 s delay, then instant across neighbours). Disabled controls say why.</td></tr></tbody></table><h3 id="hub" tabindex="-1">Hub <a class="header-anchor" href="#hub" aria-label="Permalink to &quot;Hub&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Gesture</th><th>What it does</th></tr></thead><tbody><tr><td>Click a scene row</td><td>Opens it.</td></tr><tr><td>Double click a scene row</td><td>Renames it in place.</td></tr><tr><td>Hover a scene row</td><td>Rename, Duplicate, Delete buttons.</td></tr><tr><td>Click / double click / right click a cast row</td><td>Selects / renames / menu.</td></tr><tr><td>Click a cast row chip</td><td>Align menu.</td></tr><tr><td>Hover a cast row</td><td>Mute (eye) and lock buttons.</td></tr></tbody></table><h3 id="inspector" tabindex="-1">Inspector <a class="header-anchor" href="#inspector" aria-label="Permalink to &quot;Inspector&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Gesture</th><th>What it does</th></tr></thead><tbody><tr><td>Click a number field</td><td>Types a value.</td></tr><tr><td>Drag a number field left or right</td><td>Scrubs. <kbd>Shift</kbd> finer (10x), <kbd>Ctrl</kbd> whole numbers, <kbd>Esc</kbd> reverts.</td></tr><tr><td>Right click anywhere on a property row</td><td>Row menu.</td></tr><tr><td>Click a key diamond</td><td>Animate / key / remove key / key a change.</td></tr><tr><td>Hover a property row + <kbd>K</kbd></td><td>Keys it.</td></tr><tr><td>Click a section header</td><td>Folds it (remembered per class).</td></tr><tr><td>Click a Color3 swatch or a sequence/gradient preview</td><td>Opens the editor window.</td></tr><tr><td>Click a texture palette swatch</td><td>Swaps the image.</td></tr><tr><td>Click a stack entry</td><td>Opens its block&#39;s panel (the Attached entry: its attach key).</td></tr><tr><td>Right click a stack entry</td><td>Its block menu.</td></tr><tr><td>Drag a stack entry up or down</td><td>Changes the order it runs in; <kbd>Esc</kbd> puts it back.</td></tr><tr><td>Click a stack entry&#39;s eye</td><td>Mutes or unmutes it.</td></tr></tbody></table><h3 id="editor-windows" tabindex="-1">Editor windows <a class="header-anchor" href="#editor-windows" aria-label="Permalink to &quot;Editor windows&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Gesture</th><th>What it does</th></tr></thead><tbody><tr><td>Drag the hue ring / square</td><td>Sets hue / saturation and brightness.</td></tr><tr><td>Click the sequence graph</td><td>Adds a point and keeps dragging it.</td></tr><tr><td>Drag a sequence point</td><td>Moves it (<kbd>Shift</kbd> snaps time).</td></tr><tr><td>Right click a sequence point</td><td>Removes it.</td></tr><tr><td>Drag the envelope bar</td><td>Widens or narrows the spread.</td></tr><tr><td>Click the gradient bar</td><td>Adds a stop.</td></tr><tr><td>Drag / right click / double click a gradient stop</td><td>Moves / removes / opens its colour picker.</td></tr><tr><td>Click / right click a saved swatch</td><td>Applies / rename and delete menu.</td></tr></tbody></table><h3 id="viewport" tabindex="-1">Viewport <a class="header-anchor" href="#viewport" aria-label="Permalink to &quot;Viewport&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Gesture</th><th>What it does</th></tr></thead><tbody><tr><td>Click a body part, joint dot or bone</td><td>Picks it; <kbd>Ctrl</kbd> adds or removes.</td></tr><tr><td>Click empty space</td><td>Clears the pick and Studio&#39;s selection.</td></tr><tr><td>Click outside the scene</td><td>Selects the model in Studio; <kbd>Ctrl</kbd> toggles.</td></tr><tr><td><kbd>Alt</kbd>+click outside the scene</td><td>Selects the part itself in Studio; <kbd>Ctrl</kbd> toggles.</td></tr><tr><td>Drag a gizmo handle</td><td>Turns or moves the picked joints. <kbd>Ctrl</kbd> flips the snapping; <kbd>Esc</kbd> or right click cancels.</td></tr><tr><td>Drag a resize handle</td><td>Resizes. <kbd>Ctrl</kbd> both sides, <kbd>Alt</kbd> keeps proportions, <kbd>Esc</kbd> cancels.</td></tr><tr><td>Press and drag a part (IK on)</td><td>IK drag of its chain.</td></tr><tr><td>Hold <kbd>P</kbd> + click a part / a joint dot / a floor or prop</td><td>Pins a spot / the whole part / anchors the picked parts&#39; pins.</td></tr><tr><td>Hold <kbd>Tab</kbd> over a part</td><td>Temporary pivot.</td></tr><tr><td><kbd>X</kbd> when not dragging</td><td>Switches FK/IK. Mid drag it locks the X axis.</td></tr><tr><td>Hold <kbd>J</kbd> over a trail</td><td>Timing mode.</td></tr><tr><td>Click / drag a trail dot or handle</td><td>Picks / reshapes.</td></tr><tr><td>Double click a trail line</td><td>Adds a key.</td></tr></tbody></table>',29)])])}const u=e(o,[["render",s]]);export{k as __pageData,u as default};
